using System;
using UnityEngine;

namespace HowToHunt.Core
{
    /// <summary>
    /// Every one-shot sound under Assets/Audio/SFX (not the guns: tools reference theirs), by file name without the
    /// extension ("tick_001", "pl_damage_3"). Generated by the editor (SoundLibraryBuilder) whenever a file there
    /// changes, and loaded once from Resources. Sfx looks clips up here.
    /// </summary>
    public sealed class SoundLibrary : ScriptableObject
    {
        public const string ResourcePath = "SoundLibrary";

        [Serializable]
        public struct Entry
        {
            public string Key;
            public AudioClip Clip;
        }

        public Entry[] Entries = Array.Empty<Entry>();
    }
}
